import { Download } from 'lucide-react';
import { useLang } from '../i18n/LangContext';
import { isStandaloneBuild } from '../lib/env';

/** Served file name of the single-file build; it is downloaded as index.html. */
export const STANDALONE_FILE = 'polish-learn-standalone.html';

export function standaloneHref(): string {
  return `${import.meta.env.BASE_URL}${STANDALONE_FILE}`;
}

/**
 * Link to the single-file build of this app (generated by `npm run build:standalone`).
 * Opened directly in Chrome or Safari it is not subject to an embedding iframe's
 * Permissions Policy, so the microphone works normally.
 */
export function StandaloneDownload({ variant = 'banner' }: { variant?: 'banner' | 'inline' | 'icon' }) {
  const { tr } = useLang();
  if (isStandaloneBuild) return null;
  const label = tr(
    'הורד כאפליקציה עצמאית (HTML) להפעלה מלאה עם מיקרופון בטלפון ובמחשב',
    'Download as a standalone app (HTML) for full microphone support on phone and desktop',
  );
  const common = { href: standaloneHref(), download: 'index.html', target: '_blank', rel: 'noopener' } as const;

  if (variant === 'icon') {
    return (
      <a {...common} title={label} aria-label={label} className="grid size-9 place-items-center rounded-full text-slate-600 hover:bg-slate-100">
        <Download className="size-5" />
      </a>
    );
  }
  if (variant === 'inline') {
    return (
      <a {...common} className="inline-flex items-center gap-2 rounded-xl bg-slate-900 px-4 py-2.5 text-sm font-semibold text-white shadow active:scale-95">
        <Download className="size-4 shrink-0" aria-hidden />
        {label}
      </a>
    );
  }
  return (
    <a {...common} className="flex w-full items-center justify-center gap-2 bg-slate-900 px-4 py-2.5 text-center text-sm font-bold text-white shadow-md hover:bg-slate-800 active:bg-slate-950">
      <Download className="size-5 shrink-0" aria-hidden />
      <span>{label}</span>
    </a>
  );
}
